// Browser-local diagnostic helpers. No user input is persisted or executed.
// Source review 2026-10-10: ValveSoftware/Proton README runtime options;
// docs.mesa3d.org/envvars.html; flightlessmango/MangoHud README;
// doitsujin/dxvk README; KhronosGroup/Vulkan-Loader LoaderDebugging.md;
// NVIDIA 580.105.08 README primerenderoffload.html; NixOS/nixpkgs graphics.nix.
// Requirements depend on the actual bundled release, not a guessed latest version.
const b = (en, de) => ({ en, de });
const read = (command, en, de, requirements = b('Run in the affected user session; this command only reads information. The named tool must already be available.', 'In der betroffenen Benutzersitzung ausführen; der Befehl liest nur Informationen. Das genannte Werkzeug muss vorhanden sein.')) => ({ command, interpretation: b(en, de), kind: 'read-only', requirements });
const temporary = (command, en, de, requirements, rollback) => ({ command, interpretation: b(en, de), kind: 'temporary', requirements, rollback });
const choice = (id, en, de, next) => ({ id, label: b(en, de), next });
const question = (en, de, whyEn, whyDe, choices, extra = {}) => ({ question: b(en, de), why: b(whyEn, whyDe), choices, ...extra });
const outcome = (en, de, bodyEn, bodyDe, extra = {}) => ({ heading: b(en, de), body: b(bodyEn, bodyDe), ...extra });

